/*
 * HappyAgent-only chat surfaces with no shared counterpart: the user-input prompt, the
 * model/effort/permission control menus, and the `/` command palette rows.
 * Layout is flexbox throughout; colors and type come only from theme roles.
 */

/* ---- User input prompt ----------------------------------------------------- */

.happy-agent-input {
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: 100%;
    box-sizing: border-box;
    font-family: var(--happy-font-ui);
}

/* A question in a transcript is a quiet inline response block. It follows the
   same measure as the composer without introducing another card or table. */
.happy-agent-input[data-variant="card"] {
    gap: 0;
    padding: 0;
    background: transparent;
    border: 0;
}

/* Match the composer's actual card edges, not only the shared max measure. */
.happy-conversation .happy-agent-input[data-variant="card"] {
    width: auto;
    /* The scrollbar overlays the transcript, so it is exactly as wide as the
       dock. The dock's own side insets (`.happy-conversation__dock > *`) put
       this block's painted edges on the composer's. */
    margin-right: 20px;
    margin-left: 12px;
}

.happy-agent-input__questions {
    display: flex;
    flex-direction: column;
    gap: 20px;
    width: 100%;
}

/*
 * A fieldset is sized by its own contents rather than by its flex parent, so
 * without this the option rows would stop at the longest label and leave the
 * rest of the measure empty. Zeroing the intrinsic minimum lets the ordinary
 * stretch apply and the options run the full width of the column.
 */
.happy-agent-input__question {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    width: 100%;
    min-inline-size: 0;
    border: none;
}

.happy-agent-input__legend {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 0;
    width: 100%;
