.happy-agent-control[data-variant="ghost"] .happy-agent-control__trigger:hover:not(:disabled),
.happy-agent-control[data-variant="ghost"][data-open] .happy-agent-control__trigger:not(:disabled) {
    color: var(--text);
    opacity: 1;
}

.happy-agent-control[data-variant="ghost"] .happy-agent-control__value {
    font-weight: 500;
    color: inherit;
}

.happy-agent-control[data-variant="ghost"] .happy-agent-control__label {
    color: inherit;
}

/* The chevron is the one piece of chrome the quiet form drops: the value is
   already the affordance, and pointing at it opens the menu. */
.happy-agent-control[data-variant="ghost"] .happy-agent-control__chevron {
    display: none;
}

/* ---- Live transcript activity --------------------------------------------
 *
 * The entry is the trailing half of the working-status line: the same 14px
 * secondary type as the clock and phase beside it, sized to its own text so
 * the line can put it at the far end or drop it to the next line whole.
 *
 * Its trailing inset mirrors the 30px the status text and prose start from on
 * the left, so the line is framed evenly. A flex box lets the summary shrink
 * and ellipsize inside that inset rather than spill across it when narrow.
 */
.happy-agent-activity-transcript {
    box-sizing: border-box;
    display: flex;
    height: 24px;
    min-width: 0;
    padding: 2px 30px 2px 0;
    color: var(--text-secondary);
    font-family: var(--happy-font-ui);
    font-synthesis: none;
}

.happy-agent-activity-transcript__row {
    display: flex;
    align-items: baseline;
    height: 20px;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--happy-radius-sm);
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: left;
}

.happy-agent-activity-transcript__row:not(:disabled) {
    cursor: pointer;
}

.happy-agent-activity-transcript__row:disabled {
    opacity: 1;
}

.happy-agent-activity-transcript__row:focus-visible {
    outline: 2px solid var(--radio-active);
    outline-offset: 1px;
}

.happy-agent-activity-transcript__primary {
    display: flex;
    align-items: baseline;
    gap: 6px;
    min-width: 0;
    height: 20px;
    overflow: hidden;
    color: inherit;
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.happy-agent-activity-transcript__primary > span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.happy-agent-activity-transcript__separator {
    flex: none;
    color: var(--input-placeholder);
}

/* Full-window transparent dismissal layer beneath the popover; leaves flow. */
.happy-agent-control__backdrop {
    position: fixed;
    inset: 0;
    z-index: calc(var(--happy-z-overlay) - 1);
    border: none;
    background: transparent;
    cursor: default;
}

/* Popover overlays out of flow directly beneath its trigger. Its 4px offset is
   padding rather than a gap so a pointer travelling from the trigger to the menu
   never leaves the control, which is what keeps the hover form open. */
.happy-agent-control__popover {
    position: absolute;
    top: 100%;
    left: 0;
    z-index: var(--happy-z-overlay);
    padding-top: 4px;
}

/* A control parked at the right edge of a header would push its popover off the
   window if it opened rightwards, so it hangs from the trigger's right edge. */
.happy-agent-control__popover[data-align="end"] {
    left: auto;
    right: 0;
}

.happy-agent-control__popover[data-placement="above"] {
    top: auto;
    bottom: 100%;
    padding-top: 0;
    padding-bottom: 4px;
}

/* ---- Command palette rows -------------------------------------------------- */

.happy-agent-command-palette__list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    /* Inset the rows past the shell's 14px corner radius so their own rounded
       hover corners never sit inside the palette's corner field (which the
       nested-radius contract would otherwise require to be concentric). */
    padding: 6px;
}

.happy-agent-command-palette__item {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 8px 10px;
    border: none;
    border-radius: var(--happy-radius-sm);
    background: transparent;
    cursor: pointer;
    text-align: left;
}

.happy-agent-command-palette__item:hover {
    background: var(--surface-selected);
}

.happy-agent-command-palette__icon {
    flex: none;
    display: inline-flex;
    color: var(--text-secondary);
}

.happy-agent-command-palette__item-body {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
    flex: 1 1 auto;
}

.happy-agent-command-palette__item-label {
    font-size: 14px;
    font-weight: 600;
    color: var(--text);
}

.happy-agent-command-palette__item-description {
    font-size: 12px;
    color: var(--text-secondary);
}

.happy-agent-command-palette__slash {
    flex: none;
    font-family: var(--happy-font-mono);
    font-size: 12px;
    color: var(--text-secondary);
}

.happy-agent-command-palette__empty {
    margin: 0;
    padding: 12px;
    text-align: center;
    color: var(--text-secondary);
}
